// ═══════════════════════════════════════════════════════════════════════
//  THE ONLY NODE YOU EDIT. One { … } block per service to watch.
// ═══════════════════════════════════════════════════════════════════════
//
//  name    REQUIRED. What the owner should hear it called.
//  url     REQUIRED. Prefer an internal compose address (http://app:8000)
//          over the public one — you want to know the SERVICE is down, not
//          that Caddy or DNS is having a moment. Use the public URL only when
//          the public path is what you are actually testing.
//  expect  Optional, default 200. Expected HTTP status.
//  agent   Optional, default 'orion' — Mark VI's own maintenance custodian,
//          which is whose job this is. 'centurion' if you would rather it
//          came from security.
//
//  Auth: internal Igor endpoints need X-API-Key. /health is the exception —
//  it is the one unauthenticated path (CLAUDE.md), which is exactly what makes
//  it the right thing to ping.
//
const SERVICES = [

  { name: 'Igor (app)',  url: 'http://app:8000/health' },
  { name: 'Sandbox',     url: 'http://sandbox:9000/health' },

  // { name: 'H.İ.S.A.R.', url: 'http://hisar:8600/health' },
  // { name: 'Public site', url: 'https://your.domain/health', agent: 'centurion' },

];

// ── Nothing below this line needs editing ───────────────────────────────
const out = [];
SERVICES.forEach(s => {
  if (!s || !s.url || !s.name) { return; }
  out.push({ json: {
    name: String(s.name),
    url: String(s.url),
    expect: s.expect || 200,
    agent: (s.agent || 'orion').trim(),
  }, pairedItem: { item: 0 } });
});
return out;

const store = $getWorkflowStaticData('global');
const down = store.down || {};
const cfg = $('Service list').all();
const out = [];

$input.all().forEach((item, i) => {
  const conf = (cfg[i] && cfg[i].json) || {};
  const name = conf.name || ('#' + i);
  const res = item.json || {};
  const code = Number(res.statusCode || res.status || 0);
  const healthy = code === Number(conf.expect || 200);
  const wasDown = Boolean(down[name]);

  // EDGE-TRIGGERED, both directions. A service that stays down must not send
  // 288 identical pushes a day, and coming back is worth exactly one message
  // so you know it is over without going to look.
  if (!healthy && !wasDown) {
    down[name] = true;
    out.push({ json: {
      event: 'down', name, url: conf.url, code: code || 'no response',
      agent: conf.agent || 'orion',
    }, pairedItem: { item: i } });
  } else if (healthy && wasDown) {
    down[name] = false;
    out.push({ json: {
      event: 'recovered', name, url: conf.url, code,
      agent: conf.agent || 'orion',
    }, pairedItem: { item: i } });
  }
});

store.down = down;
// Everything steady = no items = no turn.
return out;
